edits.replace:
/* PATCH(B10 2026-09-22): the catalog name is authoritative.
   og() is the single id -> project boundary (see the A6 note above), and it
   returned the payload's stored name unchanged. Four of the five labs name
   themselves correctly, but a payload that kept the project factory's
   placeholder ("New Circuit" / "project-main") surfaced that placeholder as
   the circuit name in the title bar -- the one string a user reads to know
   which lab they opened. Overwrite it with the catalog entry's name, which is
   what the Gallery path already did (`u.entry?.name ?? d.name`). The stored
   id/name are repaired too (see the three example-identity repairs), so this
   is a belt-and-braces guard for any payload added later, not the only fix. */
function og(e){
  let t=ig.find(t=>t.id===e);
  if(!t || t.requiresUnlock && !dg()) return null;
  let n=structuredClone(t.project);
  n.name=t.name;
  return n;
}
